--
-- Name: get_auth(text); Type: FUNCTION; Schema: pgbouncer; Owner: supabase_admin
--

CREATE FUNCTION pgbouncer.get_auth(p_usename text) RETURNS TABLE(username text, password text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
  BEGIN
      RAISE DEBUG 'PgBouncer auth request: %', p_usename;

      RETURN QUERY
      SELECT
          rolname::text,
          CASE WHEN rolvaliduntil < now()
              THEN null
              ELSE rolpassword::text
          END
      FROM pg_authid
      WHERE rolname=$1 and rolcanlogin;
  END;
  $_$;


ALTER FUNCTION pgbouncer.get_auth(p_usename text) OWNER TO supabase_admin;

--
-- Name: agendar_apresentacao(uuid, timestamp with time zone, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.agendar_apresentacao(_apresentador uuid, _inicio timestamp with time zone, _titulo text, _lead_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  _cfg apresentadores_config%rowtype;
  _ini_br timestamp := _inicio at time zone 'America/Sao_Paulo';
  _id uuid;
begin
  if auth.uid() is null then
    raise exception 'não autenticado';
  end if;
  select * into _cfg from apresentadores_config c
   where c.user_id = _apresentador and c.ativo;
  if _cfg.user_id is null then
    raise exception 'este apresentador não está com agendamento ativo';
  end if;
  if _inicio <= now() then
    raise exception 'horário no passado';
  end if;
  if not (extract(dow from _ini_br)::int = any(_cfg.dias)) then
    raise exception 'o apresentador não atende neste dia da semana';
  end if;
  if _ini_br::time < _cfg.hora_inicio
     or (_ini_br::time + make_interval(mins => _cfg.duracao_min)) > _cfg.hora_fim then
    raise exception 'fora da janela de horário do apresentador';
  end if;

  begin
    insert into agenda_eventos
      (titulo, inicio, fim, vendedor, criado_por, tipo, status, lead_id)
    values
      (_titulo, _inicio, _inicio + make_interval(mins => _cfg.duracao_min),
       _apresentador, auth.uid(), 'apresentacao', 'marcado', _lead_id)
    returning id into _id;
  exception when exclusion_violation then
    raise exception 'este horário acabou de ser ocupado — escolha outro';
  end;
  return _id;
end;
$$;


ALTER FUNCTION public.agendar_apresentacao(_apresentador uuid, _inicio timestamp with time zone, _titulo text, _lead_id uuid) OWNER TO postgres;

--
-- Name: agendar_retorno(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.agendar_retorno(_lead_id uuid, _quando timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare _uid uuid := auth.uid();
begin
  if _uid is null then raise exception 'Não autenticado'; end if;
  update public.leads
     set status = 'retorno', proxima_acao_em = _quando,
         atribuido_a = coalesce(atribuido_a, _uid), atualizado_em = now()
   where id = _lead_id
     and (atribuido_a = _uid or atribuido_a is null or public.eh_admin());
  if not found then raise exception 'Lead não encontrado ou sem permissão'; end if;
  insert into public.lead_eventos (lead_id, tipo, descricao, autor)
  values (_lead_id, 'status',
          'Retorno agendado para ' || to_char(_quando at time zone 'America/Sao_Paulo', 'DD/MM/YYYY'),
          _uid);
end;
$$;


ALTER FUNCTION public.agendar_retorno(_lead_id uuid, _quando timestamp with time zone) OWNER TO postgres;

--
-- Name: analise_vendedores(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.analise_vendedores(_periodo text DEFAULT 'mes'::text) RETURNS TABLE(user_id uuid, nome text, ramal text, ligacoes bigint, atendidas bigint, acima_30s bigint, acima_60s bigint, media_dia numeric, agendadas bigint, vendidas bigint, pontos bigint, pontos_mes_atual bigint, pontos_mes_anterior bigint, variacao_pct numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  _agora_br timestamp := now() at time zone 'America/Sao_Paulo';
  _desde timestamptz;
  _dias numeric;
  _ini_mes timestamptz;
  _ini_mes_ant timestamptz;
  _corte_mes_ant timestamptz;
begin
  if not eh_admin() then
    raise exception 'apenas o administrador pode ver a análise';
  end if;

  if _periodo = 'hoje' then
    _desde := (_agora_br::date)::timestamp at time zone 'America/Sao_Paulo';
    _dias := 1;
  elsif _periodo = 'semana' then
    _desde := (_agora_br::date - 6)::timestamp at time zone 'America/Sao_Paulo';
    _dias := 7;
  elsif _periodo = 'ano' then
    _desde := date_trunc('year', _agora_br) at time zone 'America/Sao_Paulo';
    _dias := extract(doy from _agora_br);
  else
    _desde := date_trunc('month', _agora_br) at time zone 'America/Sao_Paulo';
    _dias := extract(day from _agora_br);
  end if;

  _ini_mes := date_trunc('month', _agora_br) at time zone 'America/Sao_Paulo';
  _ini_mes_ant := date_trunc('month', _agora_br - interval '1 month') at time zone 'America/Sao_Paulo';
  _corte_mes_ant := _ini_mes_ant + (now() - _ini_mes);

  return query
  with m as (
    select p.user_id as uid, p.nome as vnome, p.ramal as vramal,
      (select count(*) from calls c where c.user_id = p.user_id and c.direcao = 'saida'
         and coalesce(c.iniciada_em, c.criado_em) >= _desde) as lig,
      (select count(*) from calls c where c.user_id = p.user_id and c.direcao = 'saida'
         and coalesce(c.duracao_seg, 0) > 0
         and coalesce(c.iniciada_em, c.criado_em) >= _desde) as atd,
      (select count(*) from calls c where c.user_id = p.user_id and c.direcao = 'saida'
         and coalesce(c.duracao_seg, 0) > 30
         and coalesce(c.iniciada_em, c.criado_em) >= _desde) as a30,
      (select count(*) from calls c where c.user_id = p.user_id and c.direcao = 'saida'
         and coalesce(c.duracao_seg, 0) > 60
         and coalesce(c.iniciada_em, c.criado_em) >= _desde) as a60,
      (select count(*) from agenda_eventos a where coalesce(a.criado_por, a.vendedor) = p.user_id
         and a.tipo = 'apresentacao' and a.status <> 'cancelado' and a.criado_em >= _desde) as agd,
      public.vendas_reais(p.user_id, _desde) as vnd,
      (select count(*) from calls c where c.user_id = p.user_id and c.direcao = 'saida'
         and coalesce(c.iniciada_em, c.criado_em) >= _ini_mes) as ma_lig,
      (select count(*) from calls c where c.user_id = p.user_id and c.direcao = 'saida'
         and coalesce(c.duracao_seg, 0) > 0
         and coalesce(c.iniciada_em, c.criado_em) >= _ini_mes) as ma_atd,
      (select count(*) from agenda_eventos a where coalesce(a.criado_por, a.vendedor) = p.user_id
         and a.tipo = 'apresentacao' and a.status <> 'cancelado' and a.criado_em >= _ini_mes) as ma_agd,
      public.vendas_reais(p.user_id, _ini_mes) as ma_vnd,
      (select count(*) from calls c where c.user_id = p.user_id and c.direcao = 'saida'
         and coalesce(c.iniciada_em, c.criado_em) >= _ini_mes_ant
         and coalesce(c.iniciada_em, c.criado_em) < _corte_mes_ant) as mp_lig,
      (select count(*) from calls c where c.user_id = p.user_id and c.direcao = 'saida'
         and coalesce(c.duracao_seg, 0) > 0
         and coalesce(c.iniciada_em, c.criado_em) >= _ini_mes_ant
         and coalesce(c.iniciada_em, c.criado_em) < _corte_mes_ant) as mp_atd,
      (select count(*) from agenda_eventos a where coalesce(a.criado_por, a.vendedor) = p.user_id
         and a.tipo = 'apresentacao' and a.status <> 'cancelado' and a.criado_em >= _ini_mes_ant
         and a.criado_em < _corte_mes_ant) as mp_agd,
      public.vendas_reais(p.user_id, _ini_mes_ant, _corte_mes_ant) as mp_vnd
    from profiles p
    where p.ativo = true and p.ramal is not null
  )
  select m.uid, m.vnome, m.vramal,
    m.lig, m.atd, m.a30, m.a60,
    round(m.lig::numeric / greatest(_dias, 1), 1),
    m.agd, m.vnd,
    m.lig * 1 + m.atd * 2 + m.agd * 10 + m.vnd * 50,
    m.ma_lig * 1 + m.ma_atd * 2 + m.ma_agd * 10 + m.ma_vnd * 50,
    m.mp_lig * 1 + m.mp_atd * 2 + m.mp_agd * 10 + m.mp_vnd * 50,
    case
      when (m.mp_lig * 1 + m.mp_atd * 2 + m.mp_agd * 10 + m.mp_vnd * 50) > 0
      then round(((m.ma_lig * 1 + m.ma_atd * 2 + m.ma_agd * 10 + m.ma_vnd * 50)
                - (m.mp_lig * 1 + m.mp_atd * 2 + m.mp_agd * 10 + m.mp_vnd * 50)) * 100.0
                / (m.mp_lig * 1 + m.mp_atd * 2 + m.mp_agd * 10 + m.mp_vnd * 50), 0)
      else null
    end
  from m
  order by 11 desc, 2;
end;
$$;


ALTER FUNCTION public.analise_vendedores(_periodo text) OWNER TO postgres;

