--
-- Name: buscar_conhecimento(uuid, public.vector, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.buscar_conhecimento(_campanha uuid, _emb public.vector, _limite integer DEFAULT 3) RETURNS TABLE(assunto text, gatilho text, resposta text, similaridade double precision)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select assunto, gatilho, resposta, 1 - (embedding <=> _emb) as similaridade
  from public.conhecimento_ia
  where embedding is not null
    and (campanha_id = _campanha or campanha_id is null)
  order by embedding <=> _emb
  limit _limite;
$$;


