--
-- Name: consolidar_dossie(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.consolidar_dossie(_lead_id uuid, _novo jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  _atual jsonb;
  _chave text;
  _valor jsonb;
begin
  if _lead_id is null or _novo is null then return null; end if;

  -- chamada por usuário logado: só quem trabalha este lead pode gravar
  if auth.uid() is not null and not public.eh_admin() then
    if not exists (
      select 1 from public.leads l
       where l.id = _lead_id and l.atribuido_a = auth.uid()
      union all
      select 1 from public.agenda_eventos ae
       where ae.lead_id = _lead_id
         and (ae.vendedor = auth.uid() or ae.criado_por = auth.uid())
    ) then
      raise exception 'Sem permissão para atualizar o dossiê deste lead';
    end if;
  end if;

  select coalesce(dossie, '{}'::jsonb) into _atual from leads where id = _lead_id;
  if _atual is null then return null; end if;

  for _chave, _valor in select * from jsonb_each(_novo) loop
    -- ignora vazios/nulos vindos da extração
    if _valor is not null
       and _valor <> 'null'::jsonb
       and btrim(coalesce(_valor #>> '{}', '')) <> '' then
      _atual := jsonb_set(_atual, array[_chave], _valor, true);
    end if;
  end loop;

  update leads
     set dossie = _atual,
         contato_nome = coalesce(nullif(btrim(_novo ->> 'nome_atendente'), ''), contato_nome),
         atualizado_em = now()
   where id = _lead_id;
  return _atual;
end;
$$;


ALTER FUNCTION public.consolidar_dossie(_lead_id uuid, _novo jsonb) OWNER TO postgres;

