--

CREATE FUNCTION public.eh_membro_lista(_lista uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (select 1 from listas where id = _lista and criada_por = auth.uid())
      or exists (select 1 from lista_membros
                  where lista_id = _lista and user_id = auth.uid() and situacao = 'participante');
$$;


