--
-- Name: funil_dia(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.funil_dia() RETURNS TABLE(user_id uuid, nome text, discadas bigint, atendidas bigint, conversas bigint, nao_atendeu bigint, caixa_postal bigint, ocupado bigint, numero_errado bigint, sem_interesse bigint, desligou bigint, em_contato bigint, retornos bigint, reunioes bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select c.user_id, p.nome,
    count(*),
    count(*) filter (where c.atendida_em is not null),
    count(*) filter (where c.atendida_em is not null and coalesce(c.duracao_seg, 0) >= 60),
    count(*) filter (where c.desfecho = 'nao_atendeu'),
    count(*) filter (where c.desfecho = 'caixa_postal'),
    count(*) filter (where c.desfecho = 'ocupado'),
    count(*) filter (where c.desfecho = 'numero_errado'),
    count(*) filter (where c.desfecho = 'sem_interesse'),
    count(*) filter (where c.desfecho = 'desligou'),
    count(*) filter (where c.desfecho = 'em_contato'),
    count(*) filter (where c.desfecho = 'retorno'),
    count(*) filter (where c.desfecho = 'reuniao')
  from calls c
  join profiles p on p.user_id = c.user_id
  where c.direcao = 'saida'
    and c.iniciada_em >= ((now() at time zone 'America/Sao_Paulo')::date)::timestamp
                         at time zone 'America/Sao_Paulo'
  group by 1, 2
  order by 3 desc;
$$;


ALTER FUNCTION public.funil_dia() OWNER TO postgres;

--
-- Name: gerar_codigo_comercial(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.gerar_codigo_comercial() RETURNS bigint
    LANGUAGE plpgsql
    AS $$
declare
  tentativa bigint;
begin
  loop
    tentativa := 1000000000 + floor(random() * 8999999999)::bigint;
    exit when not exists (
      select 1 from public.comercial_inscricoes where codigo = tentativa
    );
  end loop;
  return tentativa;
end $$;


ALTER FUNCTION public.gerar_codigo_comercial() OWNER TO postgres;

--
-- Name: horarios_disponiveis(uuid, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.horarios_disponiveis(_apresentador uuid, _dia date) RETURNS TABLE(inicio timestamp with time zone, fim timestamp with time zone, livre boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  _cfg apresentadores_config%rowtype;
  _dow text;
begin
  if auth.uid() is null then
    raise exception 'não autenticado';
  end if;
  select * into _cfg from apresentadores_config c
   where c.user_id = _apresentador and c.ativo;
  if _cfg.user_id is null then return; end if;
  _dow := extract(dow from _dia)::int::text;

  -- grade explícita (o normal). Dia sem lista = não atende naquele dia.
  if _cfg.horarios is not null and jsonb_typeof(_cfg.horarios -> _dow) = 'array' then
    return query
    with slots as (
      select ((_dia + h::time)::timestamp at time zone 'America/Sao_Paulo') as ini
      from jsonb_array_elements_text(_cfg.horarios -> _dow) as h
    )
    select s.ini,
           s.ini + make_interval(mins => _cfg.duracao_min),
           s.ini > now() and not exists (
             select 1 from agenda_eventos a
              where a.vendedor = _apresentador
                and a.tipo = 'apresentacao'
                and a.status <> 'cancelado'
                and tstzrange(a.inicio, a.fim) &&
                    tstzrange(s.ini, s.ini + make_interval(mins => _cfg.duracao_min))
           )
    from slots s
    order by s.ini;
    return;
  end if;

  -- sem grade montada: mantém o cálculo antigo (início/fim/almoço)
  if not (extract(dow from _dia)::int = any(_cfg.dias)) then return; end if;
  return query
  with slots as (
    select (h at time zone 'America/Sao_Paulo') as ini, h::time as hora_local
    from generate_series(
      (_dia + _cfg.hora_inicio)::timestamp,
      (_dia + _cfg.hora_fim)::timestamp - make_interval(mins => _cfg.duracao_min),
      make_interval(mins => _cfg.duracao_min)
    ) as h
  )
  select s.ini,
         s.ini + make_interval(mins => _cfg.duracao_min),
         s.ini > now() and not exists (
           select 1 from agenda_eventos a
            where a.vendedor = _apresentador
              and a.tipo = 'apresentacao'
              and a.status <> 'cancelado'
              and tstzrange(a.inicio, a.fim) &&
                  tstzrange(s.ini, s.ini + make_interval(mins => _cfg.duracao_min))
         )
  from slots s
  where _cfg.almoco_inicio is null or _cfg.almoco_fim is null
     or not (s.hora_local < _cfg.almoco_fim
             and (s.hora_local + make_interval(mins => _cfg.duracao_min))::time > _cfg.almoco_inicio)
  order by s.ini;
end;
$$;


ALTER FUNCTION public.horarios_disponiveis(_apresentador uuid, _dia date) OWNER TO postgres;

--
-- Name: linhas_status(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.linhas_status() RETURNS TABLE(ocupadas integer, maximo integer, atualizado_em timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select
    coalesce((select jsonb_array_length(valor::jsonb)
                from config where chave = 'em_ligacao'), 0)::int as ocupadas,
    coalesce((select nullif(valor, '')::int
                from config where chave = 'max_simultaneas'), 4)::int as maximo,
    (select atualizado_em from config where chave = 'em_ligacao') as atualizado_em;
$$;


ALTER FUNCTION public.linhas_status() OWNER TO postgres;

--
-- Name: lista_adicionar_leads(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.lista_adicionar_leads(_lista uuid, _leads uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare _n int;
begin
  if not eh_membro_lista(_lista) then raise exception 'você não participa desta lista'; end if;
  insert into lista_contatos (lista_id, lead_id, adicionado_por)
    select _lista, id, auth.uid() from leads where id = any(_leads)
    on conflict do nothing;
  get diagnostics _n = row_count;
  return _n;
end $$;


ALTER FUNCTION public.lista_adicionar_leads(_lista uuid, _leads uuid[]) OWNER TO postgres;

--
-- Name: lista_adicionar_por_nicho(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.lista_adicionar_por_nicho(_lista uuid, _nicho text, _qtd integer DEFAULT 100) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare _n int;
begin
  if not eh_membro_lista(_lista) then raise exception 'você não participa desta lista'; end if;
  with escolhidos as (
    select l.id from leads l
    where lower(trim(l.nicho)) = lower(trim(_nicho))
      and l.telefone is not null
      and l.status in ('novo', 'em_contato')
      and (l.dono is null or l.dono = auth.uid())
      and not exists (select 1 from lista_contatos x where x.lista_id = _lista and x.lead_id = l.id)
    order by l.criado_em desc nulls last
    limit greatest(_qtd, 1)
    for update of l skip locked
  ), marcados as (
    update leads set dono = auth.uid(), atualizado_em = now()
    where id in (select id from escolhidos)
    returning id
  )
  insert into lista_contatos (lista_id, lead_id, adicionado_por)
    select _lista, id, auth.uid() from marcados;
  get diagnostics _n = row_count;
  return _n;
end $$;


ALTER FUNCTION public.lista_adicionar_por_nicho(_lista uuid, _nicho text, _qtd integer) OWNER TO postgres;

--
-- Name: lista_convidar(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.lista_convidar(_lista uuid, _user uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not eh_membro_lista(_lista) then raise exception 'você não participa desta lista'; end if;
  insert into lista_membros (lista_id, user_id, situacao, convidado_por)
    values (_lista, _user, 'convidado', auth.uid())
    on conflict (lista_id, user_id) do update set situacao =
      case when lista_membros.situacao = 'recusado' then 'convidado' else lista_membros.situacao end;
end $$;


ALTER FUNCTION public.lista_convidar(_lista uuid, _user uuid) OWNER TO postgres;

--
-- Name: lista_criar(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.lista_criar(_nome text, _descricao text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare _id uuid;
begin
  insert into listas (nome, descricao, criada_por) values (trim(_nome), _descricao, auth.uid())
    returning id into _id;
  insert into lista_membros (lista_id, user_id, situacao) values (_id, auth.uid(), 'participante');
  return _id;
end $$;


ALTER FUNCTION public.lista_criar(_nome text, _descricao text) OWNER TO postgres;

--
-- Name: lista_puxar_proximo(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.lista_puxar_proximo(_lista uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare _lead_id uuid;
begin
  if not eh_membro_lista(_lista) then raise exception 'você não participa desta lista'; end if;
  select lc.lead_id into _lead_id
    from lista_contatos lc
    join leads l on l.id = lc.lead_id
    where lc.lista_id = _lista
      and l.telefone is not null
      and (lc.travado_ate is null or lc.travado_ate < now())
      and (
        (lc.situacao in ('pendente', 'em_cadencia')
          and (lc.proxima_tentativa_em is null or lc.proxima_tentativa_em <= now()))
        or (lc.situacao = 'retorno'
          and (l.proxima_acao_em is null or l.proxima_acao_em < now() - interval '3 days'))
      )
    order by lc.tentativas asc, coalesce(lc.proxima_tentativa_em, lc.criado_em) asc
    limit 1
    for update of lc skip locked;
  if _lead_id is null then return null; end if;

  update lista_contatos set travado_por = auth.uid(), travado_ate = now() + interval '10 minutes',
      situacao = case when situacao = 'retorno' then 'em_cadencia' else situacao end
    where lista_id = _lista and lead_id = _lead_id;
  update leads set atribuido_a = auth.uid(), atribuido_expira_em = now() + interval '30 minutes'
    where id = _lead_id;
  return (select to_jsonb(l.*) from leads l where l.id = _lead_id);
end $$;


ALTER FUNCTION public.lista_puxar_proximo(_lista uuid) OWNER TO postgres;

--
-- Name: lista_resetar_cadencia(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.lista_resetar_cadencia(_lista uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare _n int;
begin
  if not exists (select 1 from listas where id = _lista and (criada_por = auth.uid() or eh_admin())) then
    raise exception 'só a dona da lista pode resetar a cadência';
  end if;
  update lista_contatos set situacao = 'em_cadencia', tentativas = 0, proxima_tentativa_em = now()
    where lista_id = _lista and situacao = 'esgotado';
  get diagnostics _n = row_count;
  return _n;
end $$;


ALTER FUNCTION public.lista_resetar_cadencia(_lista uuid) OWNER TO postgres;

--
-- Name: lista_responder(uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.lista_responder(_lista uuid, _aceitar boolean) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  update lista_membros set situacao = case when _aceitar then 'participante' else 'recusado' end
    where lista_id = _lista and user_id = auth.uid();
$$;


ALTER FUNCTION public.lista_responder(_lista uuid, _aceitar boolean) OWNER TO postgres;

--
-- Name: listas_minhas(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.listas_minhas() RETURNS TABLE(id uuid, nome text, descricao text, criada_por uuid, dona_nome text, ativa boolean, cadencia jsonb, situacao_minha text, membros bigint, contatos bigint, prontos bigint, trabalhados bigint, retornos bigint, reunioes bigint, esgotados bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select l.id, l.nome, l.descricao, l.criada_por, pd.nome, l.ativa, l.cadencia,
    case when l.criada_por = auth.uid() then 'dona' else m.situacao end,
    (select count(*) from lista_membros where lista_id = l.id and situacao = 'participante'),
    (select count(*) from lista_contatos where lista_id = l.id),
    (select count(*) from lista_contatos lc join leads ld on ld.id = lc.lead_id
      where lc.lista_id = l.id and ld.telefone is not null
        and (lc.travado_ate is null or lc.travado_ate < now())
        and lc.situacao in ('pendente', 'em_cadencia')
        and (lc.proxima_tentativa_em is null or lc.proxima_tentativa_em <= now())),
    (select count(*) from lista_contatos where lista_id = l.id and tentativas > 0),
    (select count(*) from lista_contatos where lista_id = l.id and situacao = 'retorno'),
    (select count(*) from lista_contatos where lista_id = l.id and situacao = 'reuniao'),
    (select count(*) from lista_contatos where lista_id = l.id and situacao = 'esgotado')
  from listas l
  left join lista_membros m on m.lista_id = l.id and m.user_id = auth.uid()
  left join profiles pd on pd.user_id = l.criada_por
  where l.criada_por = auth.uid() or (m.user_id is not null and m.situacao <> 'recusado')
  order by l.criada_em desc;
$$;


ALTER FUNCTION public.listas_minhas() OWNER TO postgres;

--
-- Name: lote_remover(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.lote_remover(_lote text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  _uid uuid := auth.uid();
  _apagados int := 0;
  _descartados int := 0;
begin
  if _uid is null then raise exception 'Não autenticado'; end if;
  if _lote is null or trim(_lote) = '' then raise exception 'planilha inválida'; end if;

  with alvo as (
    delete from leads l
     where l.lote_importacao = _lote
       and l.dono = _uid
       and coalesce(l.tentativas, 0) = 0
       and not exists (select 1 from calls c where c.lead_id = l.id)
     returning 1)
  select count(*) into _apagados from alvo;

  with alvo as (
    update leads l
       set status = 'descartado', atribuido_a = null, atribuido_expira_em = null,
           atualizado_em = now()
     where l.lote_importacao = _lote
       and l.dono = _uid
       and l.status not in ('descartado', 'convertido')
     returning 1)
  select count(*) into _descartados from alvo;

  return jsonb_build_object('apagados', _apagados, 'descartados', _descartados);
end $$;


ALTER FUNCTION public.lote_remover(_lote text) OWNER TO postgres;

--
-- Name: lotes_disponiveis(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.lotes_disponiveis() RETURNS TABLE(lote text, disponiveis bigint, dono text, meu boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select l.lote_importacao,
         count(*) as disponiveis,
         min(p.nome) as dono,
         bool_or(l.criado_por = auth.uid()) as meu
  from leads l
  left join profiles p on p.user_id = l.criado_por
  where l.telefone is not null
    and l.lote_importacao is not null and trim(l.lote_importacao) <> ''
    -- planilha com dono só aparece no discador do próprio dono
    and (l.dono is null or l.dono = auth.uid())
    and (
      l.status = 'novo'
      or (l.status = 'retorno' and (l.proxima_acao_em is null or l.proxima_acao_em <= now()))
    )
    and (l.atribuido_a is null or l.atribuido_expira_em is null
         or l.atribuido_expira_em < now() or l.atribuido_a = auth.uid())
  group by l.lote_importacao
  order by 2 desc;
$$;


ALTER FUNCTION public.lotes_disponiveis() OWNER TO postgres;

--
-- Name: mudar_status_lead(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mudar_status_lead(_lead_id uuid, _status text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  _uid uuid := auth.uid();
  _dias int;
begin
  if _uid is null then raise exception 'Não autenticado'; end if;
  if _status not in ('novo','em_contato','retorno','reuniao_marcada','negociacao','convertido','descartado') then
    raise exception 'Status inválido: %', _status;
  end if;
  select coalesce(nullif(valor,'')::int, 30) into _dias
    from config where chave = 'posvenda_dias_padrao';
  _dias := coalesce(_dias, 30);
  update public.leads
     set status = _status, atualizado_em = now(),
         atribuido_a = coalesce(atribuido_a, _uid),
         -- fechou ou descartou: não há mais retorno de prospecção a fazer
         proxima_acao_em = case when _status in ('convertido','descartado')
                                then null else proxima_acao_em end,
         -- virou cliente: entra na régua de pós-venda; descartou: sai dela
         posvenda_proximo_em = case
           when _status = 'convertido' then coalesce(posvenda_proximo_em, now() + make_interval(days => _dias))
           when _status = 'descartado' then null
           else posvenda_proximo_em end,
         posvenda_intervalo_dias = case
           when _status = 'convertido' then coalesce(posvenda_intervalo_dias, _dias)
           when _status = 'descartado' then null
           else posvenda_intervalo_dias end
   where id = _lead_id
     and (atribuido_a = _uid or atribuido_a is null or public.eh_admin());
  if not found then raise exception 'Lead não encontrado ou sem permissão'; end if;
  insert into public.lead_eventos (lead_id, tipo, descricao, autor)
  values (_lead_id, 'status', 'Status alterado para ' || _status, _uid);
end;
$$;


ALTER FUNCTION public.mudar_status_lead(_lead_id uuid, _status text) OWNER TO postgres;

--
-- Name: nichos_disponiveis(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.nichos_disponiveis() RETURNS TABLE(nicho text, disponiveis bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select min(trim(l.nicho)) as nicho, count(*) as disponiveis
  from leads l
  where l.telefone is not null
    and l.nicho is not null and trim(l.nicho) <> ''
    -- só o que EU posso puxar: sem dono, ou meu
    and (l.dono is null or l.dono = auth.uid())
    and (
      l.status = 'novo'
      or (l.status = 'retorno' and (l.proxima_acao_em is null or l.proxima_acao_em <= now()))
    )
    and (l.atribuido_a is null or l.atribuido_expira_em is null
         or l.atribuido_expira_em < now() or l.atribuido_a = auth.uid())
  group by lower(trim(l.nicho))
  order by 1;
$$;


ALTER FUNCTION public.nichos_disponiveis() OWNER TO postgres;

--
-- Name: nivel_mentor(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.nivel_mentor(_user uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with base as (
    select avg(nota_ia) as media, count(*) as avaliadas
    from calls
    where user_id = _user and nota_ia is not null
  )
  select jsonb_build_object(
    'media', round(coalesce(media, 0), 1),
    'avaliadas', avaliadas,
    'nivel', case
      when media >= 9 and avaliadas >= 100 then 5
      when media >= 8 and avaliadas >= 60  then 4
      when media >= 7 and avaliadas >= 30  then 3
      when media >= 6 and avaliadas >= 10  then 2
      else 1
    end
  ) from base;
$$;


ALTER FUNCTION public.nivel_mentor(_user uuid) OWNER TO postgres;

--
-- Name: placar(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.placar(_periodo text DEFAULT 'hoje'::text) RETURNS TABLE(user_id uuid, nome text, ligacoes bigint, atendidas bigint, retornos_atendidos bigint, reunioes bigint, conversoes bigint, pontos bigint, nota_media numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  _agora_br timestamp := now() at time zone 'America/Sao_Paulo';
  _desde timestamptz;
begin
  if _periodo = 'semana' then
    _desde := (_agora_br::date - 6)::timestamp at time zone 'America/Sao_Paulo';
  elsif _periodo = '30dias' then
    _desde := (_agora_br::date - 29)::timestamp at time zone 'America/Sao_Paulo';
  elsif _periodo = 'total' then
    _desde := coalesce(
      (select (valor::date)::timestamp at time zone 'America/Sao_Paulo'
         from config where chave = 'placar_inicio'),
      timestamptz '-infinity');
  elsif _periodo = 'mes' then
    _desde := date_trunc('month', _agora_br) at time zone 'America/Sao_Paulo';
  else
    _desde := (_agora_br::date)::timestamp at time zone 'America/Sao_Paulo';
  end if;
  return query
    select p.*,
      (select round(avg(c.nota_ia)::numeric, 1)
         from calls c
        where c.user_id = p.user_id and c.nota_ia is not null)
    from public.placar_periodo(_desde) p;
end $$;


ALTER FUNCTION public.placar(_periodo text) OWNER TO postgres;

--
-- Name: placar_conferir(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.placar_conferir(_uid uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  _dia date := (now() at time zone 'America/Sao_Paulo')::date;
  _novo integer;
  _antigo integer;
  _nome text;
  _marco integer;
  _passado record;
begin
  if _uid is null then return; end if;
  select nome into _nome from profiles where user_id = _uid;
  if _nome is null then return; end if;

  _novo := public.pontos_do_dia(_uid, _dia);
  select pontos into _antigo from placar_dia where user_id = _uid and dia = _dia;
  _antigo := coalesce(_antigo, 0);
  if _novo <= _antigo then
    -- pode cair (ligação apagada); grava e sai sem avisar nada
    insert into placar_dia (user_id, dia, pontos) values (_uid, _dia, _novo)
      on conflict (user_id, dia) do update set pontos = excluded.pontos;
    return;
  end if;

  -- 1) marcos do dia: 50, 100, 150, 200 (e de 50 em 50 daí para cima)
  foreach _marco in array array[50, 100, 150, 200, 250, 300, 400, 500] loop
    if _antigo < _marco and _novo >= _marco then
      insert into notificacoes (tipo, user_id, nome, titulo, texto, valor, chave)
      values ('meta', _uid, _nome,
              _nome || ' bateu ' || _marco || ' pontos',
              'no dia de hoje', _marco,
              'meta:' || _dia || ':' || _marco || ':' || _uid)
      on conflict (chave) do nothing;
    end if;
  end loop;

  -- 2) ultrapassagem: quem estava na minha frente e agora está atrás
  for _passado in
    select d.user_id, p.nome, d.pontos
      from placar_dia d join profiles p on p.user_id = d.user_id
     where d.dia = _dia and d.user_id <> _uid
       and d.pontos > _antigo and d.pontos < _novo
     order by d.pontos desc
     limit 3
  loop
    insert into notificacoes (tipo, user_id, nome, titulo, texto, valor, chave)
    values ('ultrapassagem', _uid, _nome,
            _nome || ' passou ' || _passado.nome,
            _novo || ' pontos contra ' || _passado.pontos, _novo,
            -- uma vez por par por dia: senão vira zoeira a cada ligação
            'passou:' || _dia || ':' || _uid || ':' || _passado.user_id)
    on conflict (chave) do nothing;
  end loop;

  insert into placar_dia (user_id, dia, pontos) values (_uid, _dia, _novo)
    on conflict (user_id, dia) do update set pontos = excluded.pontos;
end $$;


ALTER FUNCTION public.placar_conferir(_uid uuid) OWNER TO postgres;

--
-- Name: placar_inicio(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.placar_inicio() RETURNS date
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select (valor::date) from config where chave = 'placar_inicio';
$$;


ALTER FUNCTION public.placar_inicio() OWNER TO postgres;

--
-- Name: placar_periodo(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.placar_periodo(_desde timestamp with time zone) RETURNS TABLE(user_id uuid, nome text, ligacoes bigint, atendidas bigint, retornos_atendidos bigint, reunioes bigint, conversoes bigint, pontos bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with janela as (
    select greatest(
      _desde,
      coalesce(
        (select (valor::date)::timestamp at time zone 'America/Sao_Paulo'
           from config where chave = 'placar_inicio'),
        '-infinity'::timestamptz)
    ) as desde
  ),
  base as (
    select p.user_id, p.nome,
      (select count(*) from calls c
        where c.user_id = p.user_id and c.direcao = 'saida'
          and c.criado_em >= (select desde from janela)) ligacoes,
      (select count(*) from calls c
        where c.user_id = p.user_id and c.direcao = 'saida'
          and coalesce(c.duracao_seg, 0) > 0
          and c.criado_em >= (select desde from janela)) atendidas,
      -- retorno realizado E atendido: o ciclo completo
      (select count(*) from calls c
        where c.user_id = p.user_id and c.direcao = 'saida'
          and c.era_retorno and coalesce(c.duracao_seg, 0) > 0
          and c.criado_em >= (select desde from janela)) retornos_atendidos,
      (select count(*) from agenda_eventos a
        where coalesce(a.criado_por, a.vendedor) = p.user_id and a.tipo = 'apresentacao'
          and a.status <> 'cancelado'
          and a.criado_em >= (select desde from janela)) reunioes,
      public.vendas_reais(p.user_id, (select desde from janela)) conversoes
    from profiles p
    where p.ativo = true
  )
  select user_id, nome, ligacoes, atendidas, retornos_atendidos, reunioes, conversoes,
         ligacoes * 1 + atendidas * 2 + retornos_atendidos * 3
           + reunioes * 10 + conversoes * 50 as pontos
  from base
  order by pontos desc, nome;
$$;


ALTER FUNCTION public.placar_periodo(_desde timestamp with time zone) OWNER TO postgres;

--
-- Name: pode_enviar_email(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pode_enviar_email(_para text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  _pol email_politica%rowtype;
  _hora int;
  _dia int;
begin
  select * into _pol from email_politica where id;

  if _pol.bloqueado then
    return jsonb_build_object('ok', false, 'motivo',
      coalesce('envio bloqueado: ' || _pol.motivo_bloqueio, 'envio bloqueado'));
  end if;

  if exists (select 1 from email_suprimidos where endereco = lower(trim(_para))) then
    return jsonb_build_object('ok', false, 'motivo',
      'este endereço pediu para não receber mais');
  end if;

  select count(*) into _hora from email_enviados
   where user_id = auth.uid() and situacao <> 'falhou'
     and criado_em > now() - interval '1 hour';
  if _hora >= _pol.max_por_hora then
    return jsonb_build_object('ok', false, 'motivo',
      format('limite de %s e-mails por hora atingido', _pol.max_por_hora));
  end if;

  select count(*) into _dia from email_enviados
   where user_id = auth.uid() and situacao <> 'falhou'
     and criado_em > now() - interval '24 hours';
  if _dia >= _pol.max_por_dia then
    return jsonb_build_object('ok', false, 'motivo',
      format('limite de %s e-mails por dia atingido', _pol.max_por_dia));
  end if;

  return jsonb_build_object('ok', true, 'remetente', _pol.remetente,
    'nome_remetente', _pol.nome_remetente);
end $$;


ALTER FUNCTION public.pode_enviar_email(_para text) OWNER TO postgres;

--
-- Name: pontos_do_dia(uuid, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pontos_do_dia(_uid uuid, _dia date) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with j as (
    select (_dia::timestamp at time zone 'America/Sao_Paulo') as ini,
           ((_dia + 1)::timestamp at time zone 'America/Sao_Paulo') as fim
  )
  select coalesce((
    select count(*) from calls c, j
     where c.user_id = _uid and c.direcao = 'saida'
       and c.criado_em >= j.ini and c.criado_em < j.fim
  ), 0)
  + coalesce((
    select count(*) * 2 from calls c, j
     where c.user_id = _uid and c.direcao = 'saida' and coalesce(c.duracao_seg, 0) > 0
       and c.criado_em >= j.ini and c.criado_em < j.fim
  ), 0)
  + coalesce((
    select count(*) * 3 from calls c, j
     where c.user_id = _uid and c.direcao = 'saida' and c.era_retorno
       and coalesce(c.duracao_seg, 0) > 0
       and c.criado_em >= j.ini and c.criado_em < j.fim
  ), 0)
  + coalesce((
    select count(*) * 10 from agenda_eventos a, j
     where coalesce(a.criado_por, a.vendedor) = _uid and a.tipo = 'apresentacao'
       and a.status <> 'cancelado'
       and a.criado_em >= j.ini and a.criado_em < j.fim
  ), 0);
$$;


ALTER FUNCTION public.pontos_do_dia(_uid uuid, _dia date) OWNER TO postgres;

SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: leads; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.leads (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    origem text DEFAULT 'maps'::text NOT NULL,
    empresa text NOT NULL,
    telefone text,
    endereco text,
    cidade text,
    estado text,
    nicho text,
    avaliacao numeric,
    num_avaliacoes integer,
    maps_place_id text,
    site text,
    status text DEFAULT 'novo'::text NOT NULL,
    atribuido_a uuid,
    atribuido_em timestamp with time zone,
    atribuido_expira_em timestamp with time zone,
    proxima_acao_em timestamp with time zone,
    criado_por uuid,
    criado_em timestamp with time zone DEFAULT now() NOT NULL,
    atualizado_em timestamp with time zone DEFAULT now() NOT NULL,
    motivador text,
    interesse text,
    dossie jsonb,
    contato_nome text,
    babel_user_id uuid,
    babel_contrato_chave uuid,
    babel_plano_id uuid,
    foto_url text,
    posvenda_proximo_em timestamp with time zone,
    posvenda_intervalo_dias integer,
    tentativas integer DEFAULT 0 NOT NULL,
    ultimo_desfecho text,
    ultima_tentativa_em timestamp with time zone,
    lote_importacao text,
    dono uuid,
    CONSTRAINT leads_interesse_check CHECK (((interesse = ANY (ARRAY['alto'::text, 'medio'::text, 'baixo'::text, 'nenhum'::text])) OR (interesse IS NULL))),
    CONSTRAINT leads_origem_check CHECK ((origem = ANY (ARRAY['maps'::text, 'manual'::text, 'entrada'::text, 'planilha'::text]))),
    CONSTRAINT leads_status_check CHECK ((status = ANY (ARRAY['novo'::text, 'em_contato'::text, 'retorno'::text, 'reuniao_marcada'::text, 'negociacao'::text, 'convertido'::text, 'descartado'::text])))
);


ALTER TABLE public.leads OWNER TO postgres;

--
-- Name: puxar_proximo_lead(text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.puxar_proximo_lead(_nicho text DEFAULT NULL::text, _lote text DEFAULT NULL::text, _pular uuid DEFAULT NULL::uuid) RETURNS public.leads
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  _uid uuid := auth.uid();
  _lead public.leads;
  _horas numeric;
  _carencia interval;
begin
  if _uid is null then raise exception 'Não autenticado'; end if;

  -- config pode estar ausente ou com texto inválido: nada disso pode derrubar
  -- a discagem, então qualquer problema cai no padrão de 6 horas
  begin
    select nullif(valor, '')::numeric into _horas
      from public.config where chave = 'carencia_retorno_horas';
  exception when others then _horas := null;
  end;
  _carencia := make_interval(hours => coalesce(_horas, 6)::int);

  update public.leads l
     set atribuido_a = _uid, atribuido_em = now(),
         atribuido_expira_em = now() + interval '30 minutes', atualizado_em = now()
   where l.id = (
     select id from public.leads
      where telefone is not null
        and (_pular is null or id <> _pular)
        and (_nicho is null or lower(trim(nicho)) = lower(trim(_nicho)))
        and (_lote is null or lote_importacao = _lote)
        -- contato com dono é só do dono; sem dono é da equipe
        and (dono is null or dono = _uid)
        and (
          status = 'novo'
          or (status = 'retorno' and (proxima_acao_em is null or proxima_acao_em <= now()))
        )
        and (
          atribuido_a is null
          or atribuido_a = _uid
          or (
            -- de outra pessoa: entra na fila da equipe quando a trava vence…
            (atribuido_expira_em is null or atribuido_expira_em < now())
            -- …mas retorno agendado é dela até a carência passar
            and (status <> 'retorno' or proxima_acao_em is null
                 or proxima_acao_em < now() - _carencia)
          )
        )
        and (ultima_tentativa_em is null
             or ultima_tentativa_em < now() - interval '15 minutes')
      order by
        -- o MEU retorno vencido vem antes de tudo: é compromisso assumido
        (status = 'retorno' and atribuido_a is not distinct from _uid) desc,
        (status = 'retorno') desc,
        proxima_acao_em asc nulls last,
        coalesce(tentativas, 0) asc,
        ultima_tentativa_em asc nulls first,
        (atribuido_a is not distinct from _uid) asc,
        criado_em asc
      for update skip locked
      limit 1
   )
   returning l.* into _lead;
  return _lead;
end;
$$;


ALTER FUNCTION public.puxar_proximo_lead(_nicho text, _lote text, _pular uuid) OWNER TO postgres;

--
-- Name: registrar_contato_posvenda(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.registrar_contato_posvenda(_lead_id uuid, _obs text DEFAULT NULL::text, _dias integer DEFAULT NULL::integer) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  _uid uuid := auth.uid();
  _int int;
  _prox timestamptz;
begin
  if _uid is null then raise exception 'Não autenticado'; end if;
  select coalesce(_dias, posvenda_intervalo_dias,
                  (select nullif(valor,'')::int from config where chave = 'posvenda_dias_padrao'), 30)
    into _int
    from leads where id = _lead_id;
  if not found then raise exception 'Cliente não encontrado'; end if;
  if _int < 1 or _int > 365 then raise exception 'Cadência inválida: % dias', _int; end if;
  _prox := now() + make_interval(days => _int);
  update leads
     set posvenda_proximo_em = _prox, posvenda_intervalo_dias = _int, atualizado_em = now()
   where id = _lead_id and status = 'convertido'
     and (atribuido_a = _uid or public.eh_admin());
  if not found then raise exception 'Cliente não encontrado ou sem permissão'; end if;
  insert into lead_eventos (lead_id, tipo, descricao, autor)
  values (_lead_id, 'posvenda',
          coalesce('🤝 Pós-venda: ' || nullif(trim(_obs), ''), '🤝 Contato de pós-venda registrado'),
          _uid);
  return _prox;
end;
$$;


ALTER FUNCTION public.registrar_contato_posvenda(_lead_id uuid, _obs text, _dias integer) OWNER TO postgres;

--
-- Name: registrar_desfecho(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.registrar_desfecho(_lead_id uuid, _numero text, _desfecho text, _nota text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  _call_id bigint;
  _n text := regexp_replace(coalesce(_numero, ''), '\D', '', 'g');
  _lista uuid;
  _cad jsonb;
  _h numeric;
  _max int;
  _tent int;
  _status text;
  _desde timestamptz := now() - interval '30 minutes';
  -- desfecho "de valor": houve conversa e algo saiu dela. Nunca pode ser
  -- apagado por uma tentativa que não completou.
  _vale boolean := _desfecho in ('retorno','reuniao','em_contato','sem_interesse','numero_errado');
begin
  if _desfecho not in ('nao_atendeu','caixa_postal','ocupado','numero_errado',
                       'sem_interesse','desligou','retorno','reuniao','em_contato') then
    raise exception 'desfecho inválido: %', _desfecho;
  end if;

  if _lead_id is not null then
    select status into _status from leads where id = _lead_id;
  end if;

  -- 1) a ligação deste número que ainda está sem desfecho
  select id into _call_id from calls
   where user_id = auth.uid() and iniciada_em > _desde and desfecho is null
     and (_n = '' or regexp_replace(coalesce(numero_externo,''), '\D', '', 'g')
                     like '%' || right(_n, 8))
   order by iniciada_em desc limit 1;

  -- 2) o mesmo número já tem desfecho, mas um fraco: é o mentor corrigindo o
  --    que acabou de marcar ("não atendeu" → "retorno"). Vem ANTES do palpite
  --    do passo 3, senão o desfecho certo vai parar na ligação errada.
  if _call_id is null and _vale and _n <> '' then
    select id into _call_id from calls
     where user_id = auth.uid() and iniciada_em > _desde
       and desfecho in ('nao_atendeu','caixa_postal','ocupado','desligou')
       and regexp_replace(coalesce(numero_externo,''), '\D', '', 'g')
           like '%' || right(_n, 8)
     order by iniciada_em desc limit 1;
  end if;

  -- 3) nenhuma ligação daquele número na janela: aceita a última sem desfecho.
  --    É palpite, então nunca escreve por cima de nada.
  if _call_id is null then
    select id into _call_id from calls
     where user_id = auth.uid() and iniciada_em > _desde and desfecho is null
     order by iniciada_em desc limit 1;
  end if;

  if _call_id is not null then
    update calls set desfecho = _desfecho,
      observacao = coalesce(nullif(_nota,''), observacao),
      -- ligação feita para um lead que estava em retorno: marca para o placar
      era_retorno = (_status = 'retorno')
      where id = _call_id;
  end if;

  if _lead_id is null then return; end if;

  update leads set tentativas = coalesce(tentativas,0) + 1,
    ultimo_desfecho = _desfecho, ultima_tentativa_em = now()
    where id = _lead_id;

  if _desfecho in ('nao_atendeu','caixa_postal','ocupado') then
    update leads set atribuido_a = null, atribuido_expira_em = null
      where id = _lead_id and status = 'novo';
    if _status = 'retorno' then
      update leads
         set proxima_acao_em = now() + case when _desfecho = 'caixa_postal'
                                            then interval '1 day' else interval '2 hours' end
       where id = _lead_id;
    end if;
  elsif _desfecho in ('numero_errado','sem_interesse') then
    update leads set status = 'descartado' where id = _lead_id;
  elsif _desfecho in ('desligou','em_contato') then
    update leads set status = 'em_contato' where id = _lead_id;
  end if;

  insert into lead_eventos (lead_id, tipo, descricao, autor)
    values (_lead_id, 'desfecho',
      _desfecho || coalesce(' — ' || nullif(_nota, ''), ''), auth.uid());

  select lc.lista_id into _lista from lista_contatos lc
    where lc.lead_id = _lead_id and lc.travado_por = auth.uid()
    order by lc.travado_ate desc nulls last limit 1;
  if _lista is null then return; end if;

  select cadencia into _cad from listas where id = _lista;
  _h := coalesce((_cad -> _desfecho ->> 'h')::numeric, null);
  _max := coalesce((_cad -> _desfecho ->> 'max')::int, 0);
  select tentativas into _tent from lista_contatos where lista_id = _lista and lead_id = _lead_id;

  update lista_contatos set
      tentativas = tentativas + 1,
      ultimo_desfecho = _desfecho,
      ultima_tentativa_em = now(),
      travado_por = null, travado_ate = null,
      situacao = case
        when _desfecho in ('numero_errado','sem_interesse') then 'descartado'
        when _desfecho = 'retorno' then 'retorno'
        when _desfecho = 'reuniao' then 'reuniao'
        when _max > 0 and _tent + 1 >= _max then 'esgotado'
        else 'em_cadencia' end,
      proxima_tentativa_em = case
        when _desfecho in ('nao_atendeu','caixa_postal','ocupado','desligou','em_contato')
             and _h is not null
        then now() + (_h * interval '1 hour') else null end
    where lista_id = _lista and lead_id = _lead_id;
end $$;


ALTER FUNCTION public.registrar_desfecho(_lead_id uuid, _numero text, _desfecho text, _nota text) OWNER TO postgres;

--
-- Name: resumo_sessao(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.resumo_sessao(_desde timestamp with time zone) RETURNS TABLE(discadas bigint, atendidas bigint, conversas bigint, retornos bigint, reunioes bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select count(*),
    count(*) filter (where atendida_em is not null),
    count(*) filter (where atendida_em is not null and coalesce(duracao_seg, 0) >= 60),
    count(*) filter (where desfecho = 'retorno'),
    count(*) filter (where desfecho = 'reuniao')
  from calls
  where user_id = auth.uid() and direcao = 'saida' and iniciada_em >= _desde;
$$;


ALTER FUNCTION public.resumo_sessao(_desde timestamp with time zone) OWNER TO postgres;

--
-- Name: saldo_carteira(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.saldo_carteira(_user uuid DEFAULT NULL::uuid) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce((select sum(valor) from carteira_lancamentos
                    where user_id = coalesce(_user, auth.uid())), 0)
       - coalesce((select sum(valor) from saques
                    where user_id = coalesce(_user, auth.uid())
                      and status in ('pendente','pago')), 0);
$$;


ALTER FUNCTION public.saldo_carteira(_user uuid) OWNER TO postgres;

--
-- Name: solicitar_saque(numeric, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.solicitar_saque(_valor numeric, _chave_pix text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  _uid uuid := auth.uid();
  _saldo numeric;
  _id uuid;
begin
  if _uid is null then raise exception 'Não autenticado'; end if;
  if _valor is null or _valor <= 0 then raise exception 'Valor inválido'; end if;
  if coalesce(btrim(_chave_pix), '') = '' then raise exception 'Informe a chave Pix'; end if;
  _saldo := public.saldo_carteira(_uid);
  if _valor > _saldo then
    raise exception 'Saldo insuficiente: disponível R$ %', round(_saldo, 2);
  end if;
  insert into public.saques (user_id, valor, chave_pix)
  values (_uid, _valor, btrim(_chave_pix)) returning id into _id;
  return _id;
end;
$_$;


ALTER FUNCTION public.solicitar_saque(_valor numeric, _chave_pix text) OWNER TO postgres;

--
-- Name: soltar_lead(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.soltar_lead(_lead_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update leads
     set atribuido_a = null, atribuido_em = null, atribuido_expira_em = null,
         ultima_tentativa_em = now(),   -- passou pela tela: não volta na hora
         atualizado_em = now()
   where id = _lead_id
     and (atribuido_a = auth.uid() or atribuido_a is null or eh_admin());

  update lista_contatos
     set travado_por = null, travado_ate = null
   where lead_id = _lead_id and travado_por = auth.uid();
end $$;


ALTER FUNCTION public.soltar_lead(_lead_id uuid) OWNER TO postgres;

--
-- Name: trg_agenda_marca_reuniao_fn(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_agenda_marca_reuniao_fn() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.lead_id is not null then
    update public.leads
       set status = 'reuniao_marcada', proxima_acao_em = new.inicio, atualizado_em = now()
     where id = new.lead_id;
    insert into public.lead_eventos (lead_id, tipo, descricao, autor)
    values (new.lead_id, 'agendamento',
            'Apresentação agendada: ' || new.titulo || ' em ' ||
            to_char(new.inicio at time zone 'America/Sao_Paulo', 'DD/MM HH24:MI'),
            new.vendedor);
  end if;
  return new;
end;
$$;


ALTER FUNCTION public.trg_agenda_marca_reuniao_fn() OWNER TO postgres;

--
-- Name: trg_call_dossie_fn(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_call_dossie_fn() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.dossie is not null and new.lead_id is not null
     and (tg_op = 'INSERT' or new.dossie is distinct from old.dossie) then
    perform public.consolidar_dossie(new.lead_id, new.dossie);
  end if;
  return null;
end;
$$;


ALTER FUNCTION public.trg_call_dossie_fn() OWNER TO postgres;

--
-- Name: trg_call_evento_lead_fn(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_call_evento_lead_fn() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.lead_id is not null then
    -- not exists protege contra evento duplicado em upsert/reprocesso
    insert into public.lead_eventos (lead_id, tipo, descricao, ref_call, autor)
    select new.lead_id, 'ligacao',
           'Ligação de ' || coalesce(new.direcao,'?') || ' (' || coalesce(new.status,'?') || ')',
           new.id, new.user_id
    where not exists (select 1 from public.lead_eventos
                       where ref_call = new.id and tipo = 'ligacao');
    update public.leads set atualizado_em = now(),
      status = case when status = 'novo' then 'em_contato' else status end,
      -- quem ligou fica responsável — sem isso o lead sumia das telas
      atribuido_a = coalesce(atribuido_a, new.user_id)
     where id = new.lead_id;
  end if;
  return null;
end;
$$;


ALTER FUNCTION public.trg_call_evento_lead_fn() OWNER TO postgres;

--
-- Name: trg_call_pega_nota_fn(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_call_pega_nota_fn() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare _nota record;
begin
  select * into _nota from notas_chamada
   where ramal = new.ramal and aplicada = false
     and criado_em > now() - interval '30 minutes'
   order by criado_em desc limit 1;
  if _nota.id is not null then
    new.observacao := _nota.texto;
    update notas_chamada set aplicada = true where id = _nota.id;
  end if;
  return new;
end; $$;


ALTER FUNCTION public.trg_call_pega_nota_fn() OWNER TO postgres;

--
-- Name: trg_call_vincula_lead_fn(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_call_vincula_lead_fn() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  _lead_id uuid;
  _fone10 text := right(regexp_replace(coalesce(new.numero_externo,''), '\D', '', 'g'), 10);
begin
  if _fone10 = '' or new.lead_id is not null then return new; end if;
  select id into _lead_id from public.leads
   where right(regexp_replace(coalesce(telefone,''), '\D', '', 'g'), 10) = _fone10
   order by atualizado_em desc limit 1;
  if _lead_id is not null then
    new.lead_id := _lead_id;
  end if;
  return new;
end;
$$;


ALTER FUNCTION public.trg_call_vincula_lead_fn() OWNER TO postgres;

--
-- Name: trg_lead_protege_cliente_fn(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_lead_protege_cliente_fn() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare _fone text := right(regexp_replace(coalesce(new.telefone,''), '\D', '', 'g'), 10);
begin
  if _fone <> '' and exists (
    select 1 from public.leads
     where status = 'convertido'
       and right(regexp_replace(coalesce(telefone,''), '\D', '', 'g'), 10) = _fone
  ) then
    return null;  -- descarta a inserção em silêncio: já é cliente da casa
  end if;
  return new;
end; $$;


ALTER FUNCTION public.trg_lead_protege_cliente_fn() OWNER TO postgres;

